import { readFile, writeFile } from "node:fs/promises";
import sharp from "sharp";
import { IOS_STARTUP_IMAGES } from "../app/pwa-startup-images.ts";

const projectFile = (path) => new URL(`../${path}`, import.meta.url);
const logo = await sharp(await readFile(projectFile("public/habitat-logo.webp")))
  .resize({ height: 96 })
  .webp({ quality: 90 })
  .toBuffer();
const startupImages = IOS_STARTUP_IMAGES.map(
  ({ url, media }) => `    <link rel="apple-touch-startup-image" href="${url}" media="${media}">`,
).join("\n");
const html = `<!doctype html>
<!-- Generated by scripts/generate-pwa-launch.mjs. Keep the skeleton aligned with app/loading.tsx. -->
<html lang="cs">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
    <meta name="theme-color" content="#D4A84B">
    <meta name="color-scheme" content="light">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-status-bar-style" content="default">
    <meta name="apple-mobile-web-app-title" content="Habitat Docházka">
    <link rel="manifest" href="/manifest.json">
    <link rel="apple-touch-icon" href="/apple-icon.png">
${startupImages}
    <title>Habitat Docházka</title>
    <style>
      * { box-sizing: border-box; }
      html, body { margin: 0; min-height: 100%; background: #FDF8F3; color: #3D3D3D; font-family: system-ui, sans-serif; }
      body { min-height: 100vh; min-height: 100dvh; }
      header { padding-top: env(safe-area-inset-top); background: white; border-bottom: 1px solid #F5EDE3; }
      .container { max-width: 1280px; margin: auto; padding-inline: 16px; }
      .header-row { height: 64px; display: flex; justify-content: space-between; align-items: center; }
      .logo { height: 32px; width: auto; }
      .avatar { width: 40px; height: 40px; border-radius: 50%; background: #F5EDE3; border: 1px solid #D4A84B40; }
      main { padding-top: 24px; padding-bottom: calc(96px + env(safe-area-inset-bottom)); }
      .bar { border-radius: 4px; background: #F5EDE3; }
      .heading { width: 160px; height: 28px; margin-bottom: 8px; }
      .subtitle { width: 224px; max-width: 100%; height: 16px; opacity: .7; margin-bottom: 24px; }
      .cards { display: grid; gap: 24px; }
      .card { height: 160px; padding: 24px; border: 1px solid #F5EDE3; border-radius: 12px; background: white; }
      .card-title { width: 128px; height: 20px; margin-bottom: 20px; }
      .line { height: 16px; opacity: .7; margin-bottom: 12px; }
      .short { width: 80%; }
      nav { position: fixed; inset: auto 0 0; border-top: 1px solid #F5EDE3; background: white; padding-bottom: env(safe-area-inset-bottom); }
      .tabs { height: 64px; display: flex; align-items: center; }
      .tab { flex: 1; display: flex; align-items: center; flex-direction: column; gap: 4px; padding: 8px 4px; font-size: 12px; font-weight: 500; border-radius: 8px; color: #737373; }
      .tab:first-child { background: #D4A84B1A; color: #3D3D3D; }
      .tab:first-child svg { color: #D4A84B; }
      svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
      .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
      @media (min-width: 640px) { .container { padding-inline: 24px; } }
      @media (min-width: 768px) { .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } nav { display: none; } main { padding-bottom: 24px; } }
      @media (min-width: 1024px) { .container { padding-inline: 32px; } }
    </style>
  </head>
  <body>
    <div role="status" aria-label="Načítání aplikace Habitat" aria-busy="true">
      <header><div class="container header-row">
        <img class="logo" src="data:image/webp;base64,${logo.toString("base64")}" width="296" height="96" alt="Habitat">
        <div class="avatar" aria-hidden="true"></div>
      </div></header>
      <main class="container" aria-hidden="true">
        <div class="bar heading"></div><div class="bar subtitle"></div>
        <div class="cards">
${Array.from({ length: 4 }, () => '          <div class="card"><div class="bar card-title"></div><div class="bar line"></div><div class="bar line short"></div></div>').join("\n")}
        </div>
      </main>
      <nav aria-hidden="true"><div class="tabs">
        <div class="tab"><svg viewBox="0 0 24 24"><path d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"></path></svg><span>Přehled</span></div>
        <div class="tab"><svg viewBox="0 0 24 24"><path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg><span>Omluvenka</span></div>
      </div></nav>
      <span class="sr-only">Načítání aplikace Habitat</span>
    </div>
    <noscript><a href="/">Otevřít Habitat</a></noscript>
    <script id="launch-navigation">
      // Two frames allow the static shell to paint before starting server navigation.
      // No load event, external font, or image request delays the dashboard.
      requestAnimationFrame(function () {
        requestAnimationFrame(function () {
          try {
            sessionStorage.setItem("habitat-launch-timing", JSON.stringify({
              shellMs: performance.now(),
              redirectEpochMs: performance.timeOrigin + performance.now(),
              controlled: Boolean(navigator.serviceWorker && navigator.serviceWorker.controller)
            }));
          } catch (_) { /* Storage restrictions must not prevent opening the app. */ }
          location.replace("/");
        });
      });
    </script>
  </body>
</html>
`;
await writeFile(projectFile("public/launch.html"), html);
console.log(`Generated public/launch.html (${Buffer.byteLength(html)} bytes, self-contained logo)`);
